import usePopularTags from "../../hooks/usePopularTags";

const MAX_TAGS = 50;

function renderTags(tags) {
  return (
    <ul className="tag-list-items">
      {tags.slice(0, MAX_TAGS).map((name) => (
        <li key={name}>
          <button className="tag-pill tag-default" type="button">
            {name}
          </button>
        </li>
      ))}
    </ul>
  );
}

function getContent({ tags, loading, error }) {
  if (loading) {
    return <p>Loading tags...</p>;
  }

  if (error) {
    return <p>{error}</p>;
  }

  if (tags.length > 0) {
    return renderTags(tags);
  }

  return <p>Tags list not available</p>;
}

function PopularTags() {
  const { tags, loading, error } = usePopularTags();

  return (
    <aside className="col-md-3">
      <div className="sidebar">
        <h6>Popular Tags</h6>
        <div className="tag-list">{getContent({ tags, loading, error })}</div>
      </div>
    </aside>
  );
}

export default PopularTags;

